<div class="card-header"><h2><?=e(trim((string)($user['first_name']??'').' '.(string)($user['last_name']??'')))?></h2><p><?=e((string)($user['email']??''))?></p></div>
<div class="form-grid">
<div class="field"><label for="role_id">Role <span class="required">*</span></label><select id="role_id" name="role_id" required><?php foreach($roles as $role):$rid=(int)($role['id']??0);?><option value="<?=e((string)$rid)?>" <?=((int)($user['role_id']??0)===$rid)?'selected':''?>><?=e((string)($role['name']??''))?></option><?php endforeach;?></select></div>
<div class="field"><label for="department_id">Department</label><select id="department_id" name="department_id"><option value="">No department assigned</option><?php foreach($departments as $department):$did=(int)($department['id']??0);?><option value="<?=e((string)$did)?>" <?=((int)($user['department_id']??0)===$did)?'selected':''?>><?=e((string)($department['name']??''))?></option><?php endforeach;?></select><small class="field-help">This department is automatically selected for the user when creating visits and gatepasses.</small></div>
<div class="field"><label for="status">Status <span class="required">*</span></label><select id="status" name="status" required><?php foreach(['active'=>'Active','invited'=>'Invited','disabled'=>'Disabled'] as $value=>$label):?><option value="<?=e($value)?>" <?=((string)($user['status']??'')===$value)?'selected':''?>><?=e($label)?></option><?php endforeach;?></select></div>
</div><div class="form-actions"><a class="btn btn-secondary" href="<?=e(url('user.php?id='.rawurlencode((string)$id)))?>">Cancel</a><button class="btn btn-primary" type="submit" data-loading-label="Saving..."><span data-button-label>Save changes</span></button></div></form>